import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;

public class TestMain {
    static final Object UNKNOWN = new Object();

    // ---- minimal JSON reader: null, Boolean, Long, String, List<Object>, Map<String,Object> ----
    static final class Parser {
        final String s;
        int i = 0;
        Parser(String s) { this.s = s; }
        void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        Object value() {
            ws();
            char c = s.charAt(i);
            if (c == '"') return string();
            if (c == '[') {
                i++;
                List<Object> out = new ArrayList<>();
                ws();
                if (s.charAt(i) == ']') { i++; return out; }
                while (true) {
                    out.add(value());
                    ws();
                    char d = s.charAt(i++);
                    if (d == ']') return out;
                    if (d != ',') throw new IllegalStateException("bad array at " + i);
                }
            }
            if (c == '{') {
                i++;
                Map<String, Object> out = new LinkedHashMap<>();
                ws();
                if (s.charAt(i) == '}') { i++; return out; }
                while (true) {
                    ws();
                    String k = string();
                    ws();
                    if (s.charAt(i++) != ':') throw new IllegalStateException("expected ':' at " + i);
                    out.put(k, value());
                    ws();
                    char d = s.charAt(i++);
                    if (d == '}') return out;
                    if (d != ',') throw new IllegalStateException("bad object at " + i);
                }
            }
            if (s.startsWith("null", i)) { i += 4; return null; }
            if (s.startsWith("true", i)) { i += 4; return Boolean.TRUE; }
            if (s.startsWith("false", i)) { i += 5; return Boolean.FALSE; }
            int st = i;
            if (c == '-') i++;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            return Long.valueOf(s.substring(st, i));
        }
        String string() {
            if (s.charAt(i) != '"') throw new IllegalStateException("expected string at " + i);
            i++;
            StringBuilder b = new StringBuilder();
            while (true) {
                char c = s.charAt(i++);
                if (c == '"') return b.toString();
                if (c != '\\') { b.append(c); continue; }
                char e = s.charAt(i++);
                switch (e) {
                    case 'n': b.append('\n'); break;
                    case 't': b.append('\t'); break;
                    case 'r': b.append('\r'); break;
                    case 'b': b.append('\b'); break;
                    case 'f': b.append('\f'); break;
                    case 'u': b.append((char) Integer.parseInt(s.substring(i, i + 4), 16)); i += 4; break;
                    default: b.append(e);
                }
            }
        }
    }

    @SuppressWarnings("unchecked")
    static <T> List<T> list(Object v, Function<Object, T> f) {
        List<T> out = new ArrayList<>();
        for (Object x : (List<Object>) v) out.add(f.apply(x));
        return out;
    }

    static Object toJ(Object v) {
        if (v == null) return null;
        if (v instanceof Integer) return Long.valueOf((Integer) v);
        if (v instanceof Long || v instanceof Boolean || v instanceof String) return v;
        if (v instanceof List) {
            List<Object> out = new ArrayList<>();
            for (Object x : (List<?>) v) out.add(toJ(x));
            return out;
        }
        throw new IllegalStateException("unsupported result type " + v.getClass().getName());
    }

    static String show(Object v) {
        if (v == null) return "null";
        if (v instanceof String) {
            StringBuilder b = new StringBuilder("\"");
            for (char c : ((String) v).toCharArray()) {
                if (c == '"') b.append("\\\"");
                else if (c == '\\') b.append("\\\\");
                else if (c == '\n') b.append("\\n");
                else if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
                else b.append(c);
            }
            return b.append('"').toString();
        }
        if (v instanceof List) {
            StringBuilder b = new StringBuilder("[");
            boolean first = true;
            for (Object x : (List<?>) v) {
                if (!first) b.append(',');
                first = false;
                b.append(show(x));
            }
            return b.append(']').toString();
        }
        return String.valueOf(v);
    }

    static Object call(String fn, List<Object> a) throws Exception {
        switch (fn) {
            case "div_round": return DivModes.divRound((Long) a.get(0), (Long) a.get(1), (String) a.get(2));
            case "mul_div": return DivModes.mulDiv((Long) a.get(0), (Long) a.get(1), (Long) a.get(2), (String) a.get(3));
            case "split_even": return DivModes.splitEven((Long) a.get(0), (Long) a.get(1));
            case "clamp_div": return DivModes.clampDiv((Long) a.get(0), (Long) a.get(1), (Long) a.get(2), (Long) a.get(3), (String) a.get(4));
            case "bucket": return DivModes.bucket((Long) a.get(0), (Long) a.get(1));
            default: return UNKNOWN;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
